#include <string.h>
#include "cm_clock_normal_display_check.h"
#include "cm_clock_display_mission_cases.h"
#include "cm_clock_normal_display_vectors.h"
static uint16_t field(const cm_mission_loop *r,uint16_t f){if(f<2048u)return r->image->words[f];switch(f){case 2048:return r->io->superbank;case 2049:return r->io->interrupt_enabled;case 2050:return r->io->channel11;case 2051:return r->irq.in_isr;case 2052:return r->irq.pending_danzig;case 2053:return r->transfer.interpretive;case 2054:return r->transfer.address.location;default:return r->transfer.address.bank;}}
static void patch(cm_mission_loop *r,uint16_t f,uint16_t v){if(f<2048u){r->image->words[f]=v;return;}switch(f){case 2048:r->io->superbank=v;break;case 2049:r->io->interrupt_enabled=v;break;case 2050:r->io->channel11=v;break;case 2051:r->irq.in_isr=(uint8_t)v;break;case 2052:r->irq.pending_danzig=(uint8_t)v;break;case 2053:r->transfer.interpretive=(uint8_t)v;break;case 2054:r->transfer.address.location=v;break;default:r->transfer.address.bank=v;break;}}
uint8_t cm_clock_normal_checkpoint_input(uint8_t n,apollo_overlay_state *s,cm_native_io *io,cm_mission_loop *r){uint16_t i;if(n>=9u)return 0;memset(r,0,sizeof *r);r->image=s;r->io=io;cm_clock_display_input(s,io,cm_clock_normal_numbers[n]);for(i=cm_clock_normal_before_offsets[n];i<cm_clock_normal_before_offsets[n+1u];++i)patch(r,cm_clock_normal_before_patch[i][0],cm_clock_normal_before_patch[i][1]);return 1;}
uint16_t cm_clock_normal_checkpoint_check(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){cm_native_io io,old;cm_mission_loop r,b;uint16_t failures=0,f,p,end;if(!cm_clock_normal_checkpoint_input(n,s,&io,&r))return 1;*before=*s;old=io;b=r;b.image=before;b.io=&old;if(cm_clock_normal_display_step(&r,29)!=CM_SERVICE_ADVANCED)++failures;p=cm_clock_normal_after_offsets[n];end=cm_clock_normal_after_offsets[n+1u];for(f=0;f<2056u;++f){uint16_t expected=field(&b,f);if(p<end&&cm_clock_normal_after_patch[p][0]==f)expected=cm_clock_normal_after_patch[p++][1];if(field(&r,f)!=expected)++failures;}if(p!=end||r.in_callback||r.completed_groups!=1u||!r.transfer.interpretive)++failures;return failures;}
